/* Number of levels of subdirectories needed for an export of size `size` */
static int treelevels(off_t size) {
    /* One directory level can address TREEDIRSIZE * TREEPAGESIZE bytes */
    int levels = 0;
    off_t capacity = (off_t)TREEDIRSIZE * TREEPAGESIZE;
    while (capacity < size) {
        levels++;
        /* watch overflow for huge sizes: use division check */
        capacity *= TREEDIRSIZE;  // hmm overflow risk for huge exports
    }
    return levels;
}
```

Careful with overflow: size can be up to 2^63. Capacity as off_t (int64) is: 1024*4096 = 2^22; times 1024 each level: 2^32, 2^42, 2^52, 2^62, then overflow. Levels up to ~4 for EB-scale exports. Loop guard: if capacity > OFF_MAX/TREEDIRSIZE, break (or levels > some max). Add a guard: `while (capacity < size && capacity <= OFF_MAX / TREEDIRSIZE)`.

Then construct_path:

```c
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
    int levels = treelevels(size);
    off_t block = pos / TREEPAGESIZE;
    int used = strlen(name);
    *ppos = pos % TREEPAGESIZE;
    /* directory components, from most significant */
    for (int l = levels; l > 0; l--) {
        off_t divisor = 1;
        for (int i = 0; i < l; i++) divisor *= TREEDIRSIZE;  /* TREEDIRSIZE^l */
        int idx = (block / divisor) % TREEDIRSIZE;
        used += snprintf(name + used, lenmax - used, "/T%04d", idx);
        if (used >= lenmax) err("treefile path too long");
    }
    used += snprintf(name + used, lenmax - used, "/F%04d", (int)(block % TREEDIRSIZE));
    if (used >= lenmax) err("treefile path too long");
}
```

