arguments.content:
/*
 * Tree files support.
 *
 * An export using the treefiles option is not stored in a single file,
 * but in a tree of small block files, each holding TREEPAGESIZE bytes
 * of data. The root of the tree is the (directory) name of the export;
 * every directory holds at most TREEDIRSIZE entries. Depending on the
 * size of the export, a number of subdirectory levels is used so that
 * the data of any offset in the export maps to exactly one block file:
 *
 *	exportname[/TREEXXXX]*/FILEXXXX
 *
 * Block files and the directories leading to them are created on
 * demand when data is written to them; reading from a block file that
 * does not (yet) exist yields zeroes.
 *
 * This is useful to provide a virtual block device on filesystems that
 * do not handle large files well (fuse/ftpfs, davfs and other network
 * filesystems).
 */

#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "cliserv.h"
#include "nbd-debug.h"
#include "treefiles.h"

/** Highest value an off_t can reach */
#define TREE_OFFT_MAX ~((off_t)1 << (sizeof(off_t) * 8 - 1))

/**
 * Compute the number of subdirectory levels needed to store an export
 * of the given size.
 *
 * With zero levels, the root directory can hold TREEDIRSIZE block files
 * of TREEPAGESIZE bytes each. Every extra level multiplies the capacity
 * by TREEDIRSIZE.
 *
 * @param size the total size of the export
 * @return the number of subdirectory levels required
 **/
static int treelevels(off_t size) {
	int levels = 0;
	off_t capacity = (off_t)TREEDIRSIZE * TREEPAGESIZE;

	while (capacity < size) {
		levels++;
		if (capacity > TREE_OFFT_MAX / TREEDIRSIZE)
			break;
		capacity *= TREEDIRSIZE;
	}

	return levels;
}

/**
 * Construct the path to the block file holding position @a pos of an
 * export of size @a size.
 *
 * The path is appended to @a name, which must be a buffer of at least
 * @a lenmax bytes holding the name of the root of the tree. The offset
 * within the block file is written to @a ppos.
 *
 * @param name buffer holding the root of the tree; the path is
 * 	appended to it
 * @param lenmax the size of the name buffer
 * @param size the total size of the export
 * @param pos the offset in the export for which we want the path
 * @param ppos [out] the offset within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int levels = treelevels(size);
	off_t block = pos / TREEPAGESIZE;
	int used = strlen(name);
	int i;
	int ret;

	*ppos = pos % TREEPAGESIZE;

	for (i = levels; i > 0; i--) {
		off_t divisor = 1;
		int idx;
		int j;

		for (j = 1; j < i; j++)
			divisor *= TREEDIRSIZE;
		idx = (block / divisor) % TREEDIRSIZE;
		if (used >= lenmax)
			err("treefile path too long");
		ret = snprintf(name + used, lenmax - used, "/TREE%04d", idx);
		if (ret < 0 || used + ret >= lenmax)
			err("treefile path too long");
		used += ret;
	}

	if (used >= lenmax)
		err("treefile path too long");
	ret = snprintf(name + used, lenmax - used, "/FILE%04d",
		       (int)(block % TREEDIRSIZE));
	if (ret < 0 || used + ret >= lenmax)
		err("treefile path too long");
}

/**
 * Create all directories on the path to @a path, excluding the last
 * component (which is assumed to be a file name).
 *
 * @param path the full path to a file; modified temporarily while the
 * 	directories are created
 **/
void mkdir_path(char *path) {
	struct stat st;
	char *lslash;

	if ((lslash = strrchr(path, '/')) == NULL)
		return;
	*lslash = '\0';
	if (*path != '\0' && stat(path, &st) < 0) {
		mkdir_path(path);
		if (mkdir(path, 0700) < 0 && errno != EEXIST)
			err("Could not create treefiles directory: %m");
	}
	*lslash = '/';
}

/**
 * Construct the path to the block file holding position @a pos, in a
 * newly allocated buffer.
 *
 * @param name the root of the tree
 * @param size the total size of the export
 * @param pos the offset in the export for which we want the path
 * @param ppos [out] the offset within the block file
 * @return a newly allocated buffer holding the full path to the block
 * 	file; must be freed by the caller
 **/
static char *treepath(const char *name, off_t size, off_t pos, off_t *ppos) {
	int levels = treelevels(size);
	size_t buflen = strlen(name) + 10 * (levels + 1) + 1;
	char *buf;

	buf = malloc(buflen);
	if (!buf)
		err("Could not allocate memory");
	strcpy(buf, name);
	construct_path(buf, buflen, size, pos, ppos);

	return buf;
}

/**
 * Open the block file holding position @a pos of an export of size @a
 * size. When the file does not exist and @a mode contains O_CREAT, the
 * directories leading to it are created as well.
 *
 * @param name the root of the tree
 * @param mode open(2) flags, e.g. O_RDONLY or (O_RDWR | O_CREAT)
 * @param size the total size of the export
 * @param pos the offset in the export for which we want the block file
 * @param mutex a mutex used to serialize directory creation
 * @return a file descriptor to the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char *path;
	off_t ppos;
	int fd;

	path = treepath(name, size, pos, &ppos);
	if (mode & O_CREAT) {
		pthread_mutex_lock(mutex);
		mkdir_path(path);
		pthread_mutex_unlock(mutex);
	}
	DEBUG("Opening treefile %s\n", path);
	fd = open(path, mode, 0600);
	free(path);

	return fd;
}

/**
 * Delete the block file holding position @a pos of an export of size
 * @a size. Used when the corresponding block is marked as unused (e.g.
 * by a TRIM request). It is not an error if the file does not exist.
 *
 * @param name the root of the tree
 * @param size the total size of the export
 * @param pos the offset in the export for which we want the block file
 * 	deleted
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char *path;
	off_t ppos;

	path = treepath(name, size, pos, &ppos);
	DEBUG("Deleting treefile %s\n", path);
	if (unlink(path) < 0 && errno != ENOENT)
		err_nonfatal("Could not delete treefile: %m");
	free(path);
}

