static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t maxbytes = TREEPAGESIZE - (a % TREEPAGESIZE);
	int fhandle;
	ssize_t retval;

	if (len > maxbytes)
		len = maxbytes;
	fhandle = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->treefiles_lock);
	if (fhandle < 0) {
