 * Flush all block files in the tree rooted at @a dir, and the
 * directories themselves.
 *
 * @param dir the directory to flush
 * @return 0 on success, nonzero on failure
 **/
static int treefiles_fsync_dir(const char *dir) {
	DIR *dirh;
	struct dirent *entry;
	int dfd;
	int retval = 0;

	dirh = opendir(dir);
	if (!dirh)
		return -1;
	dfd = dirfd(dirh);
	while ((entry = readdir(dirh)) != NULL) {
		char *path;
		int fd;

		if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, ".."))
			continue;
		path = g_strdup_printf("%s/%s", dir, entry->d_name);
		if (entry->d_type == DT_DIR) {
			retval = treefiles_fsync_dir(path);
		} else {
			fd = open(path, O_RDONLY);
			if (fd < 0) {
				retval = -1;
			} else {
				if (fsync(fd) < 0)
					retval = -1;
				close(fd);
			}
		}
		g_free(path);
		if (retval)
			break;
	}
	if (fsync(dfd) < 0)
		retval = -1;
	closedir(dirh);

	return retval;
}
