/**
 * Flush all block files in the tree rooted at @a dir, as well as the
 * directories themselves.
 *
 * @param dir the root of the (sub)tree to flush
 * @return 0 on success, nonzero on failure
 **/
static int treefiles_fsync_dir(const char *dir) {
	DIR *dirh;
	struct dirent *entry;
	int dfd;
	int retval = 0;

	dirh = opendir(dir);
	if (!dirh)
		return -1;
	dfd = dirfd(dirh);
	while ((entry = readdir(dirh)) != NULL) {
		_cleanup_g_free_ gchar *path = NULL;
		int isdir;
		int fd;

		if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, ".."))
			continue;
		path = g_strdup_printf("%s/%s", dir, entry->d_name);
		if (entry->d_type != DT_UNKNOWN) {
			isdir = entry->d_type == DT_DIR;
		} else {
			struct stat st;

			if (stat(path, &st) < 0) {
				retval = -1;
				break;
			}
			isdir = S_ISDIR(st.st_mode);
		}
		if (isdir) {
			retval = treefiles_fsync_dir(path);
		} else {
			fd = open(path, O_RDONLY);
			if (fd < 0) {
				retval = -1;
			} else {
				if (fsync(fd) < 0)
					retval = -1;
				close(fd);
			}
		}
		if (retval)
			break;
	}
	if (fsync(dfd) < 0)
		retval = -1;
	closedir(dirh);

	return retval;
}

